import sharp from 'sharp';
import { logger, requestContext } from './logger.js';
import { tracer } from './tracer.js';

// ─── OpenAI image layer generation ──────────────────────────────────────────
// Every layer of a layered slide (background, elements, effects, icon sheets)
// is generated by ONE model: gpt-image-2.5-flare — OpenAI's fast GPT Image 2.5
// variant, which supports transparent backgrounds and reference images.
// Env-overridable like every other model id in the codebase.
export const LAYER_IMAGE_MODEL = process.env.OPENAI_LAYER_IMAGE_MODEL || 'gpt-image-2.5-flare';
// Quality per layer type (measured 2026-11-02, same layouts replayed):
// medium for everything: ~1/4 of high's cost. Backgrounds look the same; objects
// are a product decision (cost over the small loss in placement fidelity).
// Set OPENAI_LAYER_QUALITY_OBJECTS=high to bring it back; OPENAI_LAYER_IMAGE_QUALITY overrides both.
export const LAYER_IMAGE_QUALITY = {
  background: process.env.OPENAI_LAYER_IMAGE_QUALITY || process.env.OPENAI_LAYER_QUALITY_BACKGROUND || 'medium',
  objects: process.env.OPENAI_LAYER_IMAGE_QUALITY || process.env.OPENAI_LAYER_QUALITY_OBJECTS || 'medium',
};

const MOCK_MODE = !process.env.OPENAI_API_KEY || process.env.OPENAI_API_KEY === 'demo';
const OPENAI_BASE_URL = 'https://api.openai.com/v1';

// ── global priority limiter ─────────────────────────────────────────────────
// A 10-slide deck fans out to ~30-60 image calls. Without a cap, OpenAI's
// per-minute image limits turn that into a wall of 429s. Single-process
// deployment (CLAUDE.md) → an in-memory queue is enough. Lower `priority`
// runs first: backgrounds (0) before heroes (1) before everything else (2),
// so every slide gets its backdrop early and the stream feels alive.
const MAX_CONCURRENT = Math.max(1, parseInt(process.env.LAYER_IMAGE_CONCURRENCY || '16', 10));
let active = 0;
const queue = [];

function pump() {
  while (active < MAX_CONCURRENT && queue.length) {
    queue.sort((a, b) => a.priority - b.priority || a.seq - b.seq);
    const job = queue.shift();
    active++;
    job.run().then(job.resolve, job.reject).finally(() => { active--; pump(); });
  }
}

let seq = 0;
export function scheduleImageJob(priority, run) {
  return new Promise((resolve, reject) => {
    queue.push({ priority, run, resolve, reject, seq: seq++ });
    pump();
  });
}

export function limiterStats() {
  return { active, queued: queue.length, max: MAX_CONCURRENT };
}

// ── sizes ───────────────────────────────────────────────────────────────────
// gpt-image-2.5-flare accepts arbitrary WIDTHxHEIGHT (multiples of 16, aspect
// up to 3:1 — probed 2026-11-02). So every layer is generated at the EXACT
// aspect of its box: no crop, no distortion, no upscaling. Cost barely tracks
// resolution (measured, high quality: 1536x1024 = 1372 output tokens,
// 2048x1152 = 1413, 1024x1024 = 1756), so the long side is set by what the
// layer needs to look crisp on a 1920x1080 slide.
export const LONG_SIDE = { background: 2048, cluster: 2048, element: 1536 };

export function sizeForAspect(w, h, longSide = LONG_SIDE.element) {
  const r = Math.min(3, Math.max(1 / 3, w / h));
  const snap = (v) => Math.max(256, Math.round(v / 16) * 16);
  return r >= 1 ? `${snap(longSide)}x${snap(longSide / r)}` : `${snap(longSide * r)}x${snap(longSide)}`;
}

function dataUrlToBlob(dataUrl) {
  const match = /^data:([^;]+);base64,(.*)$/s.exec(dataUrl);
  const mimeType = match ? match[1] : 'image/png';
  const buffer = Buffer.from(match ? match[2] : dataUrl, 'base64');
  return new Blob([buffer], { type: mimeType });
}

// ── generateLayerImage ──────────────────────────────────────────────────────
// Returns { buffer: <PNG Buffer>, ms, usage } or null on persistent failure.
// No SVG placeholder convention here: callers decide what a failed layer means
// (whole-slide failure + refund for background/hero, drop for minor elements).
//
// opts: { prompt, size, transparent, references: [dataUrl], label, quality }
export async function generateLayerImage({ prompt, size = '1024x1024', transparent = false, references = [], label = 'layer', quality = LAYER_IMAGE_QUALITY.objects, mockSpec = null }) {
  const _tid = requestContext.getStore()?.requestId;
  const _t = Date.now();
  const stepName = `layer_image_${label}`;
  tracer.recordStep(_tid, stepName, 'started', 0);

  // TEST-ONLY provider: images come from a folder instead of the OpenAI API
  // (internal benchmarks generate them through another channel, e.g. the
  // Higgsfield connector, to avoid spending API credits). A missing image is
  // written out as a request file and replaced by a mock image so the run
  // completes; drop the generated PNG in as <key>.png and replay.
  if (process.env.LAYER_IMAGE_PROVIDER === 'files') {
    return filesProvider({ prompt, size, transparent, references, label, quality, mockSpec, t0: _t });
  }

  if (MOCK_MODE) {
    await new Promise(r => setTimeout(r, 400 + Math.random() * 900));
    const buffer = await mockLayerImage(size, transparent, mockSpec || { label });
    tracer.recordStep(_tid, stepName, 'completed', Date.now() - _t);
    return { buffer, ms: Date.now() - _t, usage: null, mock: true };
  }

  const maxAttempts = 3;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      let response;
      const background = transparent ? 'transparent' : 'opaque';
      const refs = references.filter(Boolean).slice(0, 8);
      if (refs.length > 0) {
        const form = new FormData();
        form.append('model', LAYER_IMAGE_MODEL);
        form.append('prompt', prompt);
        form.append('size', size);
        form.append('quality', quality);
        form.append('background', background);
        form.append('output_format', 'png');
        form.append('n', '1');
        refs.forEach((ref, i) => form.append('image[]', dataUrlToBlob(ref), `reference_${i}.png`));
        response = await fetch(`${OPENAI_BASE_URL}/images/edits`, {
          method: 'POST',
          headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}` },
          body: form,
          signal: AbortSignal.timeout(240_000),
        });
      } else {
        response = await fetch(`${OPENAI_BASE_URL}/images/generations`, {
          method: 'POST',
          headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({ model: LAYER_IMAGE_MODEL, prompt, size, quality, background, output_format: 'png', n: 1 }),
          signal: AbortSignal.timeout(240_000),
        });
      }

      if (!response.ok) {
        const errBody = await response.text().catch(() => '');
        // 429 is usually a rate limit (retry), but "out of credits / quota"
        // is permanent — retrying only wastes time.
        const quotaExhausted = /insufficient_quota|no credits remaining|billing/i.test(errBody);
        const isTransient = !quotaExhausted && (response.status === 429 || response.status >= 500);
        const ctx = { label, attempt, status: response.status, errBody: errBody.slice(0, 500), model: LAYER_IMAGE_MODEL, size, transparent, refs: refs.length, quotaExhausted };
        if (attempt < maxAttempts && isTransient) {
          logger.warn('layer image gen failed, retrying', ctx);
          await new Promise(r => setTimeout(r, Math.pow(2, attempt) * 1500));
          continue;
        }
        logger.error('layer image gen failed', ctx);
        tracer.recordStep(_tid, stepName, 'failed', Date.now() - _t, `HTTP ${response.status}`);
        return null;
      }

      const json = await response.json();
      const b64 = json?.data?.[0]?.b64_json;
      if (!b64) {
        if (attempt < maxAttempts) continue;
        logger.error('layer image gen returned no image', { label, model: LAYER_IMAGE_MODEL });
        tracer.recordStep(_tid, stepName, 'failed', Date.now() - _t, 'no image data');
        return null;
      }
      const ms = Date.now() - _t;
      // usage = token counts OpenAI bills on — logged so real per-slide cost
      // can be measured (see scripts/layered-benchmark.js).
      logger.info('layer image generated', { label, ms, size, quality, transparent, refs: refs.length, model: LAYER_IMAGE_MODEL, usage: json.usage || null });
      tracer.recordStep(_tid, stepName, 'completed', ms);
      return { buffer: Buffer.from(b64, 'base64'), ms, usage: json.usage || null };
    } catch (err) {
      if (attempt < maxAttempts) {
        logger.warn('layer image gen errored, retrying', { label, attempt, errorMessage: err.message });
        await new Promise(r => setTimeout(r, Math.pow(2, attempt) * 1500));
        continue;
      }
      logger.error('layer image gen errored', { label, errorMessage: err.message, model: LAYER_IMAGE_MODEL });
      tracer.recordStep(_tid, stepName, 'failed', Date.now() - _t, err.message);
      return null;
    }
  }
  return null;
}

// ── mock mode ───────────────────────────────────────────────────────────────
// Real PNGs (not SVG placeholders) so the layered pipeline, renderer, editor
// and PPTX export can all be exercised end-to-end with zero API keys.
const MOCK_HUES = ['#FF2E74', '#FF8A1F', '#00FFA3', '#4FACFE', '#B388FF', '#FFD166'];

async function mockLayerImage(size, transparent, spec) {
  const [w, h] = size.split('x').map(Number);
  const hue = MOCK_HUES[Math.abs(hashCode(spec.label || '')) % MOCK_HUES.length];
  let svg;
  if (spec.kind === 'cluster') {
    // One shape per item at its declared position, so splitting is exercised in mock mode.
    const shapes = spec.items.map((it, i) => `<rect x="${it.box.x * w + 6}" y="${it.box.y * h + 6}" width="${Math.max(4, it.box.w * w - 12)}" height="${Math.max(4, it.box.h * h - 12)}" rx="${Math.min(it.box.w * w, it.box.h * h) * 0.15}" fill="${MOCK_HUES[i % MOCK_HUES.length]}"/>`).join('');
    svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}">${shapes}</svg>`;
  } else if (spec.kind === 'sheet') {
    const { cols, rows } = spec;
    const cw = w / cols; const ch = h / rows;
    let cells = '';
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const cx = c * cw + cw / 2; const cy = r * ch + ch / 2; const s = Math.min(cw, ch) * 0.28;
        cells += `<rect x="${cx - s}" y="${cy - s}" width="${s * 2}" height="${s * 2}" rx="${s * 0.4}" fill="${MOCK_HUES[(r * cols + c) % MOCK_HUES.length]}"/>`;
      }
    }
    svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}">${cells}</svg>`;
  } else if (!transparent) {
    svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}">
      <defs><radialGradient id="g1" cx="80%" cy="20%" r="70%"><stop offset="0" stop-color="${hue}" stop-opacity="0.55"/><stop offset="1" stop-color="#0b0710" stop-opacity="0"/></radialGradient>
      <radialGradient id="g2" cx="85%" cy="90%" r="60%"><stop offset="0" stop-color="#FF8A1F" stop-opacity="0.4"/><stop offset="1" stop-color="#0b0710" stop-opacity="0"/></radialGradient></defs>
      <rect width="100%" height="100%" fill="${spec.effect ? '#000000' : '#0b0710'}"/>
      <rect width="100%" height="100%" fill="url(#g1)"/><rect width="100%" height="100%" fill="url(#g2)"/></svg>`;
  } else {
    const s = Math.min(w, h);
    const screen = spec.screen
      ? `<rect x="${w / 2 - s * 0.2}" y="${h / 2 - s * 0.38}" width="${s * 0.4}" height="${s * 0.76}" rx="${s * 0.03}" fill="#00FF00"/>`
      : '';
    const body = spec.screen
      ? `<rect x="${w / 2 - s * 0.22}" y="${h / 2 - s * 0.41}" width="${s * 0.44}" height="${s * 0.82}" rx="${s * 0.06}" fill="#1b1b22"/>`
      : `<ellipse cx="${w / 2}" cy="${h / 2}" rx="${w * 0.36}" ry="${h * 0.36}" fill="${hue}" fill-opacity="0.9"/>`;
    svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}">${body}${screen}</svg>`;
  }
  return sharp(Buffer.from(svg)).png().toBuffer();
}

function hashCode(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
  return h;
}

export const IMAGE_MOCK_MODE = MOCK_MODE;

// ── test-only "files" provider ──────────────────────────────────────────────
async function filesProvider({ prompt, size, transparent, references, label, quality, mockSpec, t0 }) {
  const fs = await import('fs');
  const path = await import('path');
  const crypto = await import('crypto');
  const dir = process.env.LAYER_IMAGE_FILES_DIR;
  if (!dir) throw new Error('LAYER_IMAGE_FILES_DIR is required with LAYER_IMAGE_PROVIDER=files');
  const key = crypto.createHash('sha1').update(JSON.stringify({ prompt, size, transparent, quality })).digest('hex').slice(0, 16);
  const file = path.join(dir, `${key}.png`);
  const [w, h] = size.split('x').map(Number);
  if (fs.existsSync(file)) {
    // The external generator may only offer preset aspect ratios: fit to the requested size.
    // Test images come from preset aspect ratios; never distort them —
    // transparent layers are padded, opaque ones cropped to the exact size.
    const buffer = await sharp(file).resize(w, h, transparent
      ? { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }
      : { fit: 'cover' }).png().toBuffer();
    return { buffer, ms: Date.now() - t0, usage: null, provider: 'files' };
  }
  fs.mkdirSync(path.join(dir, 'requests'), { recursive: true });
  fs.writeFileSync(path.join(dir, 'requests', `${key}.json`), JSON.stringify({ key, label, prompt, size, transparent, quality, references: references.length }, null, 2));
  const buffer = await mockLayerImage(size, transparent, mockSpec || { label });
  return { buffer, ms: Date.now() - t0, usage: null, provider: 'files-missing' };
}
